    if (!strcmp(checkstr,"none")) check=LZMA_CHECK_NONE;
    else if (!strcmp(checkstr,"crc32")) check=LZMA_CHECK_CRC32;
    else if (!strcmp(checkstr,"crc64")) check=LZMA_CHECK_CRC64;
    else if (!strcmp(checkstr,"sha256")) check=LZMA_CHECK_SHA256;
    // read stdin
    size_t cap=1<<20, len=0;
    uint8_t *in=malloc(cap);
    size_t n;
    while ((n=fread(in+len,1,cap-len,stdin))>0) {
        len+=n;
        if (len==cap) { cap*=2; in=realloc(in,cap); }
    }
    lzma_stream strm=LZMA_STREAM_INIT;
    lzma_mt mt={0};
    mt.flags=0;
    mt.threads=threads==0? 4 : threads; // use 4? Actually use threads as given, if 0 use 4? For test, use 2?
    mt.block_size=0;
    mt.timeout=0;
    mt.preset=preset;
    mt.filters=NULL;
    mt.check=check;
    lzma_ret ret=lzma_stream_encoder_mt(&strm,&mt);
    if (ret!=LZMA_OK) { fprintf(stderr,"encoder_mt failed %d\n",ret); return 1; }
    size_t outcap=len+1024*1024;
    uint8_t *out=malloc(outcap);
    strm.next_in=in; strm.avail_in=len;
    strm.next_out=out; strm.avail_out=outcap;
    ret=lzma_code(&strm,LZMA_FINISH);
    if (ret!=LZMA_STREAM_END) { fprintf(stderr,"code failed %d\n",ret); return 1; }
    fwrite(out,1,strm.total_out,stdout);
    lzma_end(&strm);
    return 0;
}
