#include <string.h>
#include <stdint.h>

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s preset threads check\n", argv[0]);
        return 1;
    }
    uint32_t preset = (uint32_t)strtoul(argv[1], NULL, 10);
    uint32_t threads = (uint32_t)strtoul(argv[2], NULL, 10);
    const char *checkstr = argv[3];
    lzma_check check = LZMA_CHECK_CRC64;
    if (!strcmp(checkstr, "none")) check = LZMA_CHECK_NONE;
    else if (!strcmp(checkstr, "crc32")) check = LZMA_CHECK_CRC32;
    else if (!strcmp(checkstr, "crc64")) check = LZMA_CHECK_CRC64;
    else if (!strcmp(checkstr, "sha256")) check = LZMA_CHECK_SHA256;
    else { fprintf(stderr, "bad check\n"); return 1; }

    size_t cap = 1<<20, len = 0;
    uint8_t *in = malloc(cap);
    if (!in) return 1;
    size_t n;
    while ((n = fread(in+len, 1, cap-len, stdin)) > 0) {
        len += n;
        if (len == cap) {
            cap *= 2;
            uint8_t *tmp = realloc(in, cap);
            if (!tmp) { free(in); return 1; }
            in = tmp;
        }
    }
    if (ferror(stdin)) { free(in); return 1; }

    lzma_stream strm = LZMA_STREAM_INIT;
    lzma_ret ret;
    int use_mt = (threads != 1);
    if (use_mt) {
        lzma_mt mt;
        memset(&mt, 0, sizeof(mt));
        mt.flags = 0;
        if (threads == 0) {
            // Use number of cores? For small files, any >1 gives same. Use 4.
            // Try to get nproc? Use 4.
            mt.threads = 4;
        } else {
            mt.threads = threads;
        }
        mt.block_size = 0;
        mt.timeout = 0;
        mt.preset = preset;
        mt.filters = NULL;
        mt.check = check;
        ret = lzma_stream_encoder_mt(&strm, &mt);
        if (ret != LZMA_OK) {
            fprintf(stderr, "encoder_mt failed %d\n", ret);
            free(in);
            return 1;
        }
    } else {
        // single-thread: use easy encoder (ignores threads)
        // For check, easy encoder uses check param? Actually lzma_easy_encoder takes preset and check? No, easy encoder signature: lzma_easy_encoder(&strm, preset, check)
        ret = lzma_easy_encoder(&strm, preset, check);
        if (ret != LZMA_OK) {
            fprintf(stderr, "easy failed %d\n", ret);
            free(in);
            return 1;
        }
    }
    size_t outcap = len + len/3 + 1024*1024;
    if (outcap < 1024*1024) outcap = 1024*1024;
    uint8_t *out = malloc(outcap);
    if (!out) { free(in); lzma_end(&strm); return 1; }
    strm.next_in = in;
    strm.avail_in = len;
    strm.next_out = out;
    strm.avail_out = outcap;
    // Need loop in case output buffer too small? For large input, outcap may be insufficient. Loop with realloc.
    while (1) {
        ret = lzma_code(&strm, LZMA_FINISH);
        if (ret == LZMA_STREAM_END) break;
        if (ret != LZMA_OK) {
            fprintf(stderr, "code failed %d\n", ret);
            free(in); free(out); lzma_end(&strm);
            return 1;
        }
        if (strm.avail_out == 0) {
            size_t used = outcap;
            outcap *= 2;
            uint8_t *tmp = realloc(out, outcap);
            if (!tmp) { free(in); free(out); lzma_end(&strm); return 1; }
            out = tmp;
            strm.next_out = out + used;
            strm.avail_out = outcap - used;
        }
    }
    fwrite(out, 1, strm.total_out, stdout);
    free(in); free(out);
    lzma_end(&strm);
    return 0;
}
EOF
cat /workspace/mt_helper.c | head -n 20
gcc /workspace/mt_helper.c -llzma -o /tmp/mt_helper_test 2>&1 | head
echo "compile $?"
echo "hi" | /tmp/mt_helper_test 2147483654 0 crc64 2>&1 | od -An -tx1 | head
# Test preset 6 without extreme (6), threads 0
echo "hi" | /tmp/mt_helper_test 6 0 crc64 2>&1 | od -An -tx1 | head
echo "hi" | /workspace/executable -c 2>&1 | od -An -tx1 | head"}

