open(os.path.join(tmp,"a.txt"),"wb").write(b"x"*1000)
for t in [1,2,4,8,16,32,64]:
    r=subprocess.run([EXE,"-v","-v","-k","-f","-T"+str(t),os.path.join(tmp,"a.txt")], capture_output=True)
